import serial
import time

class Serial(object):
    def __init__(self, serial_port, baudrate, timeout):
        self.serial = serial.Serial(serial_port, baudrate, timeout=timeout)
        self.serial.bytesize = serial.EIGHTBITS
        self.serial.parity = serial.PARITY_NONE
        self.serial.stopbits = serial.STOPBITS_ONE

    def send_ping_frame(self, master, slave):
        # Create a new M-Bus frame with the ping command
        frame = self.create_frame(master, slave, 0x10, 0x40, 0x00, 0x40, 0x16)
        # Send the frame over the serial port
        self.serial.write(frame)

    def send_request_frame_single(self, master, slave):
        # Create a new M-Bus frame with the single-telegram request command
        frame = self.create_frame(master, slave, 0x7A, 0x00, 0x7A, 0x16)
        # Send the frame over the serial port
        self.serial.write(frame)

    def send_request_frame_multi(self, master, slave):
        # Create a new M-Bus frame with the multi-telegram request command
        frame = self.create_frame(master, slave, 0x7B, 0x00, 0x7B, 0x16)
        # Send the frame over the serial port
        self.serial.write(frame)

    def create_frame(self, master, slave, telegram_type, telegram_address, telegram_identifier, telegram_data):
        # Create the M-Bus frame
        frame = bytes([0x10, 0x7F, 0x01, telegram_type, master, slave, telegram_address, telegram_identifier, telegram_data])
        return frame

    def read(self):
        # Read the response from the serial port
        return self.serial.read(5)

